      "s.wifi.step1": "1. Installieren Sie die App (überspringen, wenn sie installiert ist)",
      "s.wifi.step1Hint": "Ladet die PhoneBox App herunter. Android fragt einmal, ob das Installieren von Apps über den Browser erlaubt werden soll.",
      "s.wifi.step2": "2. Scannen Sie diesen mit der Kamera des Telefons",
      "s.wifi.step2Hint": "Öffnen Sie den Link und wählen Sie PhoneBox . Das Telefon fordert Sie auf, den Code zu bestätigen . ",
      "s.wifi.noCableHint": "Kein USB Kabel, Entwickleroptionen oder Adb benötigt.Das Telefon und dieser Computer müssen im selben Netzwerk sein (oder beide auf Tailscale).",
