      "s.k.newShortcut": "Neue Verknüpfung",
      "s.k.noShortcuts": "Noch keine Shortcuts. Fügen Sie eine mit \"Neue Shortcut\" hinzu.",
      "s.k.macroHint": "keys:… drückt Tasten, text:… schreibt, wait:300 wartet (Millisekunden), shortcut:id führt eine andere Verknüpfung aus. if:running:spotify … else … endif führt die Schritte dazwischen nur dann aus, wenn die Bedingung stimmt (running:program, muted, on:shortcut-id, push:key; ! in front dreht es um). clipboard:… legt Text in die Zwischenablage, paste:… fügt Text durch diese ein und setzt das Kopierte zurück. {clipboard} in einem Text-, Zwischenablage- oder Einfügeschritt wird durch den Inhalt der Zwischenablage ersetzt.",
      "s.k.textHint": "{clipboard} wird durch den Text in der Zwischenablage (die ersten 10.000 Zeichen) ersetzt.",
      "s.k.clipboardWarn": "Eingegebener Text wird durch das Systemeingabewerkzeug gelesen, so dass auf einem Mac oder Linux ein kopiertes Passwort in der Prozessliste angezeigt werden kann, während es eingetippt wird. Wenn Sie {clipboard} in ein Terminal eingeben, wird alles ausgeführt, was dort kopiert wurde. Einfügen: hält seinen Text aus dem Windows Zwischenablageverlauf und der Cloud-Zwischenablage heraus und fügt den kopierten Text anschließend wieder ein (ein kopiertes Bild oder Dateien werden nicht beibehalten: die Zwischenablage bleibt leer); auf einem Mac kann Universal Clipboard ihn weiterhin mit Ihren anderen Geräten synchronisieren.",
      "s.k.macosPermission": "macOS fragt einmal, ob PhoneBoxAgent in den Systemeinstellungen › Datenschutz & Sicherheit › Barrierefreiheit zugelassen werden soll.",
