      "s.kiosk.pin": "Pin das Panel: Home und Recents bleiben auf ihm (Android fragt einmal; halten Sie Zurück und Übersicht zusammen, um zu lösen)",
      "s.kiosk.homeScreen": "Verwenden Sie das Panel als Startbildschirm des Telefons: es startet nach einem Neustart und Home kehrt zu ihm zurück (Ausschalten, um Ihren Launcher wiederzubekommen)",
      "s.kiosk.keepAwake": "Halten Sie das Telefon wach: Schalten Sie den Bildschirmschoner von Android aus (er startet am Ladegerät) und lassen Sie den Bildschirm eingeschaltet, während er angeschlossen ist (über USB gestellt)",
      "s.kiosk.openOnConnect": "Öffnen Sie PhoneBox, wenn das Telefon angeschlossen ist: Wecken Sie das Telefon auf und bringen Sie das Panel nach vorne, wann immer es sich über USB verbindet (Ausschalten, um es selbst zu öffnen, für ein Telefon, das Sie auch zum Testen von Apps verwenden)",
      "s.kiosk.followLock": "Folgen Sie der Computersperre: Schalten Sie den Telefonbildschirm aus, wenn macOS gesperrt wird; wecken Sie es auf und öffnen Sie PhoneBox, wenn macOS entsperrt wird (ADB erforderlich; entsperren Sie Handys manuell, die durch eine PIN oder ein Passwort geschützt sind)",
      "s.claude.shareConversation": "Anzeigen der Konversation auf dem Telefon (Tippen Sie auf Claude Code Sie können die neuesten Nachrichten und Schritte der Sitzung anzeigen. Dies sind Ihre Eingabeaufforderungen und Claude(Antworten von 's, nur an Ihr Handy gesendet)",
      "s.claude.onlyWhenAway": "Nur wenn ich nicht am PC bin (keine Tastatur oder Maus für eine Minute)",
