      "s.k.cycleHint": "Jedes Tippen führt die nächste Taste der Liste aus und beginnt dann wieder mit der ersten. Die Taste auf dem Telefon zeigt die zuletzt ausgeführte Taste (Icon und Name) an. Vor dem ersten Tippen wird ihre eigene angezeigt.",
      "s.k.cycleFew": "Wenn nur ein Schlüssel in der Liste ist, wird dieser Schlüssel ausgeführt. Ist keiner vorhanden, wird nichts getan. Schlüssel, die nicht mehr existieren, werden beim Speichern aus der Liste entfernt.",
