      "s.battery.leadHead": "Un téléphone qui est branché tout le temps utilise sa batterie.PhoneBox peut le garder entre deux charges.",
      "s.battery.leadMid": "Les téléphones ne peuvent pas arrêter de charger par eux-mêmes sans root, donc l'alimentation est commuté en fonction du niveau de charge.",
      "s.wh.payloadHintFull": "JSON charges utiles peuvent transporter <code>value</code>, <code>title</code>, <code>sub</code>, <code>unit</code>, <code>icon</code>, <code>color</code>, <code>level</code> (ok / warn / erreur), <code>progress</code> (0 &amp; 1 ou 0 &amp;100), <code>items</code> (une liste) et <code>ttl</code> (secondes). Le texte brut ou un nombre fonctionne également. Les notifications prennent <code>title</code>, <code>text</code>, <code>level</code>, <code>vibrate</code>, <code>seconds</code>, <code>wake</code> (allumer l'écran de nuit) et <code>page</code> (commutez vers elle).",
