      "A live picture from an IP camera (RTSP), 5 frames a second by default (1 to 10). Add the camera in Settings › General › Cameras; the computer pulls it with ffmpeg, and its address stays there.": "Une image en direct d'une caméra IP (RTSP), 5 images par seconde par défaut (1 à 10). Ajouter la caméra dans Réglages › Général › Caméras; l'ordinateur le tire avec ffmpeg, et son adresse reste là.",
