      "s.antigravity.title": "Sesiones de Antigravity",
      "s.antigravity.hint": "Muestra los chats recientes de Antigravity en el widget Sesiones de IA (desactivado por defecto). Solo se guardan los metadatos de los pasos y los contadores de tokens; los prompts, las respuestas y los argumentos de herramientas nunca se muestran, guardan ni envían.",
