      "s.feeds.urlPlaceholder": "https://example.com/feed.xml",
      "s.oled.lead": "Para pantallas OLED que muestran la misma página durante horas, el tema negro AMOLED y la pantalla nocturna también ayudan.",
      "s.oled.idleDimHint": "Un toque lo ilumina de nuevo sin presionar nada; también lo hace un cambio de página, una notificación y un mensaje de permiso.",
      "s.weather.openMeteoHint": "El teléfono pide Open-Meteo para esta ubicación solo cuando una página tiene un widget que utiliza el tiempo (tiempo, pronóstico, sol y luna, un reloj con su línea de tiempo, HTML personalizado).",
      "s.display.orientationHint": "Diseña páginas en horizontal; en vertical el panel organiza los widgets por sí mismo, de arriba a abajo.Las tabletas utilizan las mismas páginas, solo que más grandes.",
      "s.rules.countdown": "Los cambios de página cuentan en el teléfono y esperan mientras lo usas (General › Cambio de página).",
      "s.rules.pausedUntil": "Las reglas se detienen hasta {time} .",
      "s.pageSwitch.lead": "Cómo las reglas, los webhooks y el retorno inactivo cambian la página. En lugar de saltar, el teléfono muestra “Claude me necesita — cambiando a AI en 3…” con Stay and Go ahora, luego se desvanece. Nunca saca una página mientras está usando el panel, y las reglas que se activan una tras otra esperan su turno en lugar de rebotar la pantalla hacia adelante y hacia atrás.",
      "s.pageSwitch.homePageHint": "Donde van el retorno de inactividad y la tecla Atrás.",
      "s.pageSwitch.backHome": "Vuelta a casa después (segundos sin un toque, 0 = nunca)",
