      "s.obs.hint": "En OBS : Herramientas › Configuración del servidor WebSocket › <i> Habilitar el servidor WebSocket </i>; copiar la contraseña de <i> Mostrar información de conexión </i>.",
      "s.battery.leadTail": "De donde viene: un enchufe inteligente <b> en Home Assistant </b> (el teléfono en su propio cargador), o dos atajos <b> </b> , por ejemplo <code>uhubctl</code> para un hub USB con puertos conmutables.Sin la energía de USB el panel sigue funcionando sobre Wi-Fi .",
      "s.claude.hint": "Cuando Claude Code pide permiso (ejecutar un comando, editar un archivo…), el teléfono muestra la solicitud con <b> Allow </b> y <b> Deny </b> . Si el teléfono no está conectado o nadie responde a tiempo, Claude Code pregunta en la terminal como de costumbre, esto necesita un pequeño gancho en <code>~/.claude/settings.json</code>; PhoneBox lo agrega por usted (se guarda una copia de seguridad junto al archivo).",
      "s.wifi.lead": "Emparejar un teléfono conectándolo una vez más USB Después de encenderlo (y reiniciar), o sin cable: <b>Emparejar un teléfono Wi-Fi</b> Muestra un QR El teléfono entonces habla HTTPS a este PC, confía solo en el certificado de este PC y tiene que presentar una clave secreta. El teléfono y este PC deben estar en la misma red &mdash; o ambos en la misma red. <a href=\"https://tailscale.com\" target=\"_blank\" rel=\"noopener\">Tailscale</a>, que también funciona desde otro lugar o a través de Wi-Fi Networks. Windows El firewall pregunta una vez &mdash; permítalo (marque el tipo de red Tailscale También se usa).",
      "s.upd.checksBefore": "Cheques",
      "s.upd.checksAfter": "on GitHub La aplicación para el teléfono se instala en la computadora. USB Sin una solicitud en el teléfono; el agente reemplaza sus propios archivos y se reinicia.",
      "s.wh.payloadHint": "Las cargas útiles JSON pueden llevar",
      "s.k.argsPlaceholderWindows": "Ejemplo: -d D:\\Proyectos claude",
      "s.k.argsPlaceholderUnix": "Ejemplo: --new-window ~/Proyectos",
      "s.ap.fontOriginal": "Fuente original",
      "s.ap.fontSans": "Sans serif",
      "s.ap.fontRounded": "Redondeado",
