      "s.r.matchTime": "22:00-07:00",
      "s.restartApplyTitle": "Cambio de configuración Wi-Fi después de un reinicio",
      "s.ap.inheritFont": "Heredar ( {font} )",
      "s.battery.leadHead": "Un teléfono que está enchufado todo el tiempo gasta su batería, PhoneBox puede mantenerlo entre dos cargas.",
      "s.battery.leadMid": "Los teléfonos no pueden dejar de cargar por sí mismos sin root, por lo que la energía se conmuta automáticamente cuando el teléfono está cargado.",
      "s.wh.payloadHintFull": "JSON Las cargas útiles pueden llevar <code>value</code>, <code>title</code>, <code>sub</code>, <code>unit</code>, <code>icon</code>, <code>color</code>, <code>level</code> (ok / advertir / error), <code>progress</code> (0 &amp; 1 o 0 &amp;100), <code>items</code> (una lista) y <code>ttl</code> (segundos). También funciona con texto plano o un número. Las notificaciones tardan <code>title</code>, <code>text</code>, <code>level</code>, <code>vibrate</code>, <code>seconds</code>, <code>wake</code> (iluminar la pantalla nocturna) y <code>page</code> (cambiar a él).",
      "s.pair.title": "Emparejar un teléfono con {pc}",
      "s.pair.qr": "Emparejamiento del código QR",
      "s.pair.downloadQr": "Código QR para descargar la app",
      "s.pair.hosts": "El teléfono se conectará a {hosts} en el puerto {port}. El código funciona una vez, durante 5 minutos.El código QR no contiene la clave.",
      "s.pair.noHosts": "No se encontró ninguna dirección LAN o Tailscale en este equipo, por lo que el teléfono no tiene nada a qué conectarse.",
      "s.pair.copy": "Copia el enlace de emparejamiento",
      "s.pair.expired": "Cierra y vuelve a empezar.",
      "s.pair.expires": "Expira en 1 año {time}."
