      "s.k.macroHint": "keys:… preme i tasti, text:… digita, wait:300 attese (millisecondi), shortcut:id esegue un’altra scorciatoia. if:running:spotify … else … endif esegue i passaggi intermedi solo quando la condizione è valida (running:program, muted, on:shortcut-id, push:key; ! in front lo capovolge). clipboard:… mette il testo negli appunti, paste:… incolla il testo attraverso di esso e rimette quello che è stato copiato. {clipboard} in un passo testo, appunti o incolla viene sostituito da ciò che si trova negli appunti.",
