      "s.kiosk.keepAwake": "Mantenere il telefono sveglio: spegnere lo screen saver di Android (si avvia sul caricabatterie) e mantenere lo schermo acceso mentre è collegato (impostato su USB)",
      "s.kiosk.openOnConnect": "Apri PhoneBox quando il telefono è collegato: svegliare il telefono e portare il pannello in avanti ogni volta che si connette su USB (spegnerlo per aprirlo da solo, per un telefono che usi anche per testare le app)",
      "s.kiosk.followLock": "Segui il blocco del computer: spegni lo schermo del telefono quando macOS si blocca; riattivalo e apri PhoneBox quando macOS si sblocca (richiede ADB; sblocca manualmente i telefoni protetti da PIN o password)",
      "s.claude.shareConversation": "Mostra la conversazione sul telefono (tocca una sessione Claude Code per vedere i suoi messaggi recenti e passi; questi sono i tuoi prompt e le risposte di Claude, inviati solo al telefono)",
