      "s.ap.inheritFont": "Ereditare ( {font} )",
      "s.battery.leadHead": "Un telefono che è collegato tutto il tempo consuma la batteria.PhoneBox può tenerlo tra due carichi.",
      "s.battery.leadMid": "I telefoni non possono smettere di caricare da soli senza root, quindi l'alimentazione viene attivata quando si avvia il telefono.",
      "s.wh.payloadHintFull": "JSON I carichi utili possono trasportare <code>value</code>, <code>title</code>, <code>sub</code>, <code>unit</code>, <code>icon</code>, <code>color</code>, <code>level</code> (ok / avviso / errore), <code>progress</code> (0&ndash;1 o 0&ndash,100), <code>items</code> (un elenco) e <code>ttl</code> (secondi). Funziona anche il testo normale o un numero. Le notifiche <code>title</code>, <code>text</code>, <code>level</code>, <code>vibrate</code>, <code>seconds</code>, <code>wake</code> (accende lo schermo notturno) e <code>page</code> (commutare su di esso).",
      "s.pair.title": "Associare un telefono con {pc}",
