      "s.k.macroHint": "keys:… pressiona teclas, text:… digita, wait:300 waits (miliseconds), shortcut:id executa outro atalho. if:running:spotify … else … endif executa os passos entre eles somente quando a condição é cumprida (running:program, muted, on:shortcut-id, push:key; ! in front o vira). clipboard:… coloca texto na área de transferência, paste:… cola o texto por meio dele e coloca de volta o que foi copiado. {clipboard} em um passo de texto, área de transferência ou colagem é substituído pelo que está na área de transferências.",
      "s.k.textHint": "{clipboard} é substituído pelo texto na área de transferência (os primeiros 10.000 caracteres).",
      "s.k.clipboardWarn": "O texto digitado passa pela ferramenta de digitação do sistema, então em um Mac ou Linux uma senha copiada pode aparecer na lista de processos enquanto é digitada. Digitar {clipboard} em um terminal executa o que foi copiado lá. paste: mantém seu texto fora do histórico da área de transferência Windows e da área de transferências da nuvem e depois coloca de volta o texto que foi copiado (uma imagem ou arquivos copiados não são mantidos: a área de transferência fica vazia); em um Mac, a Universal Clipboard ainda pode sincronizá-lo com seus outros dispositivos.",
