      "s.kiosk.openOnConnect": "Abra o PhoneBox quando o telefone estiver conectado: acorde o telefone e traga o painel para a frente sempre que ele se conectar ao USB (desligue para abrir você mesmo, para um telefone que você também usa para testes de aplicativos)",
