      "s.cal.hint": "Para o público <b>Agenda</b> Cole um endereço do iCalendar (ICS): Google Agenda › Configurações › seu calendário › <i>Endereço secreto em formato iCal</i>Outlook › Configurações › Calendário › Calendários compartilhados › <i>Publicar um calendário</i> (link do ICS); iCloud › compartilhar como calendário público (link do<code>webcal://</code> Os endereços permanecem neste computador.",
      "s.ha.tokenHint": "Para o widget <b> Home Assistant </b>. Crie um token no Home Assistant › seu perfil › Segurança › <i> Tokens de acesso duradouro </i> . O token permanece neste computador; o telefone só vê as entidades da lista de widgets (o Home Assistant também pode enviar valores e notificações para o painel, consulte Webhooks).",
      "s.obs.enable": "Conecte-se a OBS (para o widget <b> OBS </b>, o widget On air e regras)",
      "s.obs.hint": "Em OBS : Ferramentas › Configurações do Servidor WebSocket › <i> Ativar o servidor WebSocket </i> ; copie a senha de <i> Show Connect Info </i> .",
      "s.battery.leadTail": "de onde vem: a <b>plug inteligente em Home Assistant</b> (o telefone em seu próprio carregador), ou dois <b>atalhos</b>, por exemplo <code>uhubctl</code> para um USB hub com portas comutáveis. Sem USB energia o painel continua a correr sobre Wi-Fi.",
      "s.claude.hint": "Quando o Claude Code pede permissão (executar um comando, editar um arquivo…), o telefone mostra a solicitação com <b> Permitir </b> e <b> Negar </b> . Se o telefone não estiver conectado ou ninguém responder a tempo, o Claude Code pergunta no terminal como de costume. Isso precisa de um pequeno gancho em <code>~/.claude/settings.json</code>; O PhoneBox adiciona isso para você (um backup é mantido ao lado do arquivo).",
      "s.wifi.lead": "Emparelhe um telefone conectando-o uma vez sobre USB depois de ligar (e reiniciar), ou sem um cabo: <b>Emparelhar um telefone Wi-Fi</b> mostra um QR O telefone então fala HTTPS para este PC, confia apenas no certificado deste PC e tem que apresentar uma chave secreta. O telefone e este PC devem estar na mesma rede &mdash; ou ambos em um computador com o mesmo endereço IP. <a href=\"https://tailscale.com\" target=\"_blank\" rel=\"noopener\">Tailscale</a>, que também funciona a partir de outro lugar ou em separado Wi-Fi redes de comunicação. Windows O firewall pergunta uma vez &mdash; permita-o (marque o tipo de rede Tailscale utilizações, também).",
      "s.upd.checksBefore": "Verificações",
      "s.upd.checksAfter": "O aplicativo do telefone é instalado sobre o USB sem um prompt no telefone; o agente substitui seus próprios arquivos e reinicia.O agente substitui os arquivos de backup que foram criados para o GitHub a cada 6 horas.",
      "s.wh.payloadHint": "As cargas úteis JSON podem transportar",
      "s.k.argsPlaceholderWindows": "por exemplo -d D:\\Projectos claude",
      "s.k.argsPlaceholderUnix": "Por exemplo --new-window ~/Projetos",
