      "s.adv.notYet": "Nog niet gevonden",
      "s.cal.hint": "Voor de avond <b>Agenda</b> Een iCalendar-adres (ICS) plakken: Google Agenda › Instellingen › uw agenda › Uw kalender toevoegen aan een andere agenda. <i>Geheime adres in iCal-formaat</i>Outlook › Instellingen › Agenda › Gedeelde agenda's › <i>Een agenda publiceren</i> (ICS-koppeling); iCloud › delen als openbare agenda (<code>webcal://</code> De adressen blijven op deze computer staan.",
      "s.ha.tokenHint": "Voor de <b> Home Assistant </b> widget. Maak een token aan in Home Assistant › uw profiel › Beveiliging › <i> Langdurige toegangstoken </i> . Het token blijft op deze computer staan; de telefoon ziet alleen de entiteiten die zijn widgets lijst bevatten. (Home Assistant kan ook waarden en notificaties naar het paneel pushen, zie Webhooks.)",
      "s.obs.enable": "Maak verbinding met OBS (voor de widget <b> OBS </b>, de On air widget en regels)",
      "s.obs.hint": "In OBS : Tools › WebSocket Server Settings › <i> Schakel de WebSocket server in </i>; kopieer het wachtwoord vanuit <i> Show Connect Info </i>.",
      "s.battery.leadTail": "Waar het vandaan komt: een <b> smart plug in Home Assistant </b> (de telefoon op zijn eigen lader), of twee <b> shortcuts </b> , bijvoorbeeld <code>uhubctl</code> voor een USB hub met schakelbare poorten.Zonder USB stroom blijft het paneel draaien over Wi-Fi .",
      "s.claude.hint": "Wanneer Claude Code om toestemming vraagt (om een commando uit te voeren, een bestand aan te passen…), dan toont de telefoon het verzoek met <b> Allow </b> en <b> Deny </b> . Als de telefoon niet verbonden is of niemand op tijd antwoordt, vraagt Claude Code zoals gewoonlijk in de terminal. Dit vereist een kleine hook in <code>~/.claude/settings.json</code>; PhoneBox voegt deze voor u toe (een back-up wordt naast het bestand bewaard).",
      "s.wifi.lead": "Koppel een telefoon door deze één keer in te steken USB Nadat je dit hebt ingeschakeld (en opnieuw hebt opgestart), of zonder kabel: <b>Een telefoon koppelen Wi-Fi</b> toont een QR De telefoon communiceert dan via HTTPS met deze pc, vertrouwt alleen het certificaat van deze pc en moet een geheime sleutel tonen. De telefoon en de pc moeten op hetzelfde netwerk zijn &mdash; of beide op dezelfde router staan. <a href=\"https://tailscale.com\" target=\"_blank\" rel=\"noopener\">Tailscale</a>, die ook werkt vanuit een andere plaats of over aparte Wi-Fi netwerken. Windows Firewall vraagt eenmaal &mdash; toestaan (vink het netwerktype aan Tailscale Ook voor andere toepassingen).",
      "s.upd.checksBefore": "Controles",
      "s.upd.checksAfter": "aan GitHub De telefoonapp wordt geïnstalleerd op de computer. USB Zonder een prompt op de telefoon; de agent vervangt zijn eigen bestanden en start opnieuw.",
      "s.wh.payloadHint": "JSON payloads kunnen dragen",
