      "s.k.macroHint": "keys:… naciska klawisze, text:… wpisuje, wait:300 czeka (milisekund), shortcut:id uruchamia inny skrót. if:running:spotify … else … endif wykonuje kroki pomiędzy tylko wtedy, gdy warunek jest spełniony (running:program, muted, on:shortcut-id, push:key; ! w przedniej części odwraca go). clipboard:… umieszcza tekst w schowku, paste:… wkleja tekst przez niego i umieszcza z powrotem to, co zostało skopiowane. {clipboard} w kroku tekstu, schowka lub wklejania jest zastępowany tym, co znajduje się w schowku.",
      "s.k.textHint": "{clipboard} jest zastępowany tekstem ze schowka (pierwsze 10 000 znaków).",
      "s.k.clipboardWarn": "Wpisany tekst przechodzi przez narzędzie do pisania systemu, więc na komputerze Mac lub Linux skopiowane hasło może pojawić się na liście procesów podczas wpisywania.Wpisanie {clipboard} w terminalu uruchamia to, co zostało tam skopiowane. wklejenie: zachowuje swój tekst poza historią schowka Windows i schowkiem chmury, a następnie umieszcza z powrotem skopiowany tekst (skopiowany obraz lub pliki nie są zachowywane: schowek pozostaje pusty); na komputerze Mac Universal Clipboard może nadal synchronizować go z innymi urządzeniami.",
