      "s.k.longPressHint": "Przytrzymaj klawisz na telefonie przez pół sekundy, aby uruchomić ten inny klucz zamiast Zapisz nowy klucz najpierw, aby wybrać go tutaj.",
      "s.k.cycle": "Przechodzenie przez inne klawisze",
