      "s.k.cycleAdd": "Dodawanie klucza",
      "s.k.cycleHint": "Każde dotknięcie uruchamia następny klawisz z listy, a następnie rozpoczyna się od pierwszego. Klawisz na telefonie pokazuje ten, który został uruchomiony ostatnio (jego ikona i nazwa); przed pierwszym dotknięciem pokazuje swój własny.",
      "s.k.cycleFew": "Jeśli na liście jest tylko jeden klucz, to ten klucz wykonuje po prostu ten klucz. Jeśli nie ma żadnego, to nic nie robi. Klucze, które już nie istnieją są usuwane z listy podczas zapisywania.",
