      "s.oled.lead": "Для OLED экранов, которые показывают одну и ту же страницу в течение часов. AMOLED черная тема и ночной экран также помогают.",
      "s.oled.idleDimHint": "Касание освещает его снова без нажатия ничего; так же переключатель страницы, уведомление и подсказка разрешений.",
      "s.weather.openMeteoHint": "Телефон просит Open-Meteo для этого местоположения только в то время, как страница имеет виджет, который использует погоду (погода, прогноз, солнце и луна, часы с его погоды линии, Custom HTML).",
      "s.display.orientationHint": "Вы создаете страницы в горизонтальном режиме; в портретном панели располагает виджеты самостоятельно, сверху вниз. Таблетки используют те же страницы, только больше.",
      "s.rules.countdown": "Переключение страницы отсчитывает время на телефоне и ожидает, пока вы его используете (Общие › Переключение страниц).",
      "s.rules.pausedUntil": "Правила приостанавливается до {time} .",
      "s.pageSwitch.lead": "Как правила, webhooks и idle return изменить страницу. Вместо прыжка, телефон показывает “ Claude нуждается в мне — переключение на AI в 3…” с Stay and Go сейчас, а затем выпадает. Он никогда не тянет страницу, пока вы используете панели, и правила, которые стреляют один за другим ждать их очереди, а не отскочить экран туда-сюда.",
