      "s.k.macroHint": "keys:… нажимает клавиши, text:… типы, wait:300 ожидания (миллисекунды), shortcut:id запускает другой ярлык. if:running:spotify … else … endif выполняет шаги между только когда условие сохраняется (running:program, muted, on:shortcut-id, push:key; ! впереди переворачивает его). clipboard:… ставит текст в буфер обмена, paste:… вставляет текст через него и возвращает то, что было скопировано. {clipboard} в тексте, буфера обмена или вставить шаг заменяется тем, что находится в буфере обмена.",
      "s.k.textHint": "{clipboard} заменяется текстом в буфере обмена (первые 10 000 символов).",
      "s.k.clipboardWarn": "Введенный текст проходит через системный инструмент ввода, так что на Mac или Linux скопированный пароль может появляться в списке процессов во время его ввода. Ввод {clipboard} в терминал запускает то, что было скопировано там. paste: сохраняет свой текст из истории буфера обмена Windows и буфера обменов облака, а затем возвращает копированный текст (скопированное изображение или файлы не хранятся: буфер обмена остается пустым); на Mac Universal Clipboard все еще может синхронизировать его с другими устройствами.",
