      "s.k.cycleHint": "Каждый кран запускает следующий ключ из списка, а затем начинает сначала. Клавиши на телефоне показывают тот, который работал последний (его значок и имя); перед первым краном он показывает свой собственный.",
      "s.k.cycleFew": "Если в списке только один ключ, то этот ключ просто выполняет его; если же ни одного, то он не делает ничего. Ключи, которые больше не существуют, выпадают из списка при сохранении.",
