      "s.restartApplyTitle": "Настройки Wi-Fi изменяются после перезапуска",
      "s.ap.inheritFont": "Наследование ( {font} )",
      "s.battery.leadHead": "Телефон, который подключен к сети все время носит его батарея. PhoneBox может держать его между двумя",
      "s.battery.leadMid": "уровней, включая и выключая питание телефона. Телефоны не могут остановить зарядку сами по себе без корня, так что власть переключается",
      "s.wh.payloadHintFull": "JSON полезные грузы могут перевозить <code>value</code>, <code>title</code>, <code>sub</code>, <code>unit</code>, <code>icon</code>, <code>color</code>, <code>level</code> (ОК / предупреждение / ошибка), <code>progress</code> (0 или 100), <code>items</code> (перечень) и <code>ttl</code> (секунды). Обычный текст или число также работает. Уведомления <code>title</code>, <code>text</code>, <code>level</code>, <code>vibrate</code>, <code>seconds</code>, <code>wake</code> (подсветка ночного экрана) и <code>page</code> (переключитесь на него).",
      "s.pair.title": "Парирование телефона с {pc}",
