      "s.wh.payloadHintFull": "JSON 有效载荷可携带的 <code>value</code>, <code>title</code>, <code>sub</code>, <code>unit</code>, <code>icon</code>, <code>color</code>, <code>level</code> (OK/警告/错误 ) , <code>progress</code> 10. 对于非法贩运人口的行为，应当采取适当措施。 <code>items</code> (一份清单)和 <code>ttl</code> 单纯文本或数字也可以使用。 通知需要 <code>title</code>, <code>text</code>, <code>level</code>, <code>vibrate</code>, <code>seconds</code>, <code>wake</code> (点亮夜间屏幕)和 <code>page</code> 我们都不会忘记它。",
